#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,shutil,subprocess,sys
from datetime import datetime
UI=""""""
CSS=""""""
START="/* AV_V2_1_STAFF_ROTA_START */";END="/* AV_V2_1_STAFF_ROTA_END */"
def unpack(x):return zlib.decompress(base64.b64decode(x)).decode()
root=Path.cwd();u=root/"app/dashboard/ui.tsx";c=root/"app/globals.css"
if not u.exists() or not c.exists() or not(root/"package.json").exists():print("Run from coach-hours-v1 project root.");sys.exit(1)
stamp=datetime.now().strftime("%Y%m%d-%H%M%S");b=root/".av-backups"/f"pre-v2.1.0-{stamp}";(b/"app/dashboard").mkdir(parents=True,exist_ok=True);shutil.copy2(u,b/"app/dashboard/ui.tsx");shutil.copy2(c,b/"app/globals.css");print("Backup:",b)
u.write_text(unpack(UI),encoding="utf-8");old=c.read_text()
if START in old and END in old:old=old.split(START,1)[0].rstrip()+"\n"+old.split(END,1)[1].lstrip()
c.write_text(old.rstrip()+"\n\n"+START+"\n"+unpack(CSS).strip()+"\n"+END+"\n")
r=subprocess.run(["npm","run","build"],cwd=root)
if r.returncode:print("BUILD FAILED. Nothing pushed.");sys.exit(r.returncode)
print("BUILD PASSED.")
if "--deploy" in sys.argv:
 subprocess.run(["git","add","app/dashboard/ui.tsx","app/globals.css"],cwd=root,check=True)
 d=subprocess.run(["git","diff","--cached","--quiet"],cwd=root)
 if d.returncode:
  subprocess.run(["git","commit","-m","Release v2.1.0 staff rota workflow"],cwd=root,check=True);subprocess.run(["git","push","origin","main"],cwd=root,check=True);print("Pushed. Wait for Vercel Ready.")
